local function C_17()
	local script = LMG2L["LocalScript_17"];
	local gui = script.Parent	
	local UserInputService = game:GetService("UserInputService")	
	local TweenService = game:GetService("TweenService")	

	local dragging = false	
	local dragStart	
	local startPos	
	local dragSpeed = 0.33	

	-- เริ่มลากเมื่อคลิกหรือแตะ GUI	
	gui.InputBegan:Connect(function(input)	
	    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then	
	        dragging = true	
	        dragStart = input.Position	
	        startPos = gui.Position	

	        -- เมื่อหยุดคลิก/ปล่อยนิ้ว	
	        input.Changed:Connect(function()	
	            if input.UserInputState == Enum.UserInputState.End then	
	                dragging = false	
	            end	
	        end)	
	    end	
	end)	

	-- ติดตามเมาส์/นิ้วทุกการเคลื่อนไหว ไม่จำกัดแค่บน GUI	
	UserInputService.InputChanged:Connect(function(input)	
	    if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then	
	        local delta = input.Position - dragStart	
	        local targetPos = UDim2.new(	
	            startPos.X.Scale,	
	            startPos.X.Offset + delta.X,	
	            startPos.Y.Scale,	
	            startPos.Y.Offset + delta.Y	
	        )	

	        -- ใช้ Tween ให้ GUI ลื่นไหล	
	        local tween = TweenService:Create(gui, TweenInfo.new(dragSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Position = targetPos})	
	        tween:Play()	
	    end	
	end)	
end;
